package com.kelompok4.oralhealthplus.feature.chatbot

import androidx.compose.ui.text.AnnotatedString
import androidx.compose.ui.text.SpanStyle
import androidx.compose.ui.text.buildAnnotatedString
import androidx.compose.ui.text.font.FontStyle
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.withStyle

data class TextSegment(
    val text: String,
    val isBold: Boolean = false,
    val isItalic: Boolean = false
)

object ChatTextFormatter {
    private val HEADING_REGEX = Regex("^#{1,6}\\s+(.+)$")
    private val BULLET_REGEX = Regex("^[*\\-]\\s+(.+)$")
    private val INLINE_TOKEN_REGEX = Regex("(\\*\\*(.+?)\\*\\*)|(`([^`]+)`)|((?<!\\*)\\*([^\\s*][^*]*?[^\\s*]|[^\\s*])\\*(?!\\*))")
    private val EXCESS_NEWLINES_REGEX = Regex("\n{3,}")

    fun parseSegments(raw: String): List<TextSegment> {
        val normalized = raw
            .replace("\r\n", "\n")
            .replace("\r", "\n")
            .replace(EXCESS_NEWLINES_REGEX, "\n\n")
            .trim()

        if (normalized.isEmpty()) return emptyList()

        val result = mutableListOf<TextSegment>()
        val lines = normalized.split("\n")

        lines.forEachIndexed { index, rawLine ->
            val trimmed = rawLine.trimStart()
            val headingMatch = HEADING_REGEX.matchEntire(trimmed)

            when {
                trimmed.isEmpty() -> {
                    // Blank line separator handled by newline appending below
                }
                headingMatch != null -> {
                    val cleanHeading = stripStrayMarkdown(headingMatch.groupValues[1].trim())
                    if (cleanHeading.isNotEmpty()) {
                        result.add(TextSegment(text = cleanHeading, isBold = true))
                    }
                }
                else -> {
                    val bulletMatch = BULLET_REGEX.matchEntire(trimmed)
                    val lineContent = if (bulletMatch != null) {
                        "• ${bulletMatch.groupValues[1].trim()}"
                    } else {
                        trimmed
                    }
                    parseInlineSegments(lineContent, result)
                }
            }

            if (index < lines.lastIndex) {
                result.add(TextSegment(text = "\n"))
            }
        }

        return result
    }

    fun formatForDisplay(raw: String): AnnotatedString {
        val segments = parseSegments(raw)
        return buildAnnotatedString {
            for (segment in segments) {
                if (segment.isBold || segment.isItalic) {
                    withStyle(
                        SpanStyle(
                            fontWeight = if (segment.isBold) FontWeight.SemiBold else FontWeight.Normal,
                            fontStyle = if (segment.isItalic) FontStyle.Italic else FontStyle.Normal
                        )
                    ) {
                        append(segment.text)
                    }
                } else {
                    append(segment.text)
                }
            }
        }
    }

    private fun parseInlineSegments(line: String, out: MutableList<TextSegment>) {
        var cursor = 0
        for (match in INLINE_TOKEN_REGEX.findAll(line)) {
            if (match.range.first > cursor) {
                val plain = stripStrayMarkdown(line.substring(cursor, match.range.first))
                if (plain.isNotEmpty()) out.add(TextSegment(text = plain))
            }

            val boldText = match.groups[2]?.value
            val codeText = match.groups[4]?.value
            val italicText = match.groups[6]?.value

            when {
                boldText != null -> {
                    val cleaned = stripStrayMarkdown(boldText)
                    if (cleaned.isNotEmpty()) out.add(TextSegment(text = cleaned, isBold = true))
                }
                codeText != null -> {
                    val cleaned = stripStrayMarkdown(codeText)
                    if (cleaned.isNotEmpty()) out.add(TextSegment(text = cleaned))
                }
                italicText != null -> {
                    val cleaned = stripStrayMarkdown(italicText)
                    if (cleaned.isNotEmpty()) out.add(TextSegment(text = cleaned, isItalic = true))
                }
            }

            cursor = match.range.last + 1
        }

        if (cursor < line.length) {
            val tail = stripStrayMarkdown(line.substring(cursor))
            if (tail.isNotEmpty()) out.add(TextSegment(text = tail))
        }
    }

    private fun stripStrayMarkdown(text: String): String {
        return text
            .replace("**", "")
            .replace("__", "")
            .replace("`", "")
    }
}
